import React, { useEffect, useRef } from 'react';

/**
 * Modos:
 *  - Preferido (grupos): <ProductSlider groups={[{ id, variant:'cards', products:[{id,imageUrl,name,priceLabel}] }]} />
 *  - Legado (imágenes):  <ProductSlider images={[{id,imageUrl}]} />
 *
 * Un “slide” = 1 grupo. Navegación por páginas. Drag/Swipe habilitado.
 */
export default function ProductSlider({ id, groups = [], images = [] }) {
  const trackRef = useRef(null);
  const rootRef  = useRef(null);

  // Drag / swipe
  useEffect(() => {
    const el = trackRef.current;
    if (!el) return;
    let isDown = false, startX = 0, scrollLeft = 0;
    const pt = (e) => (e.touches ? e.touches[0].pageX : e.pageX);
    const down = (e) => { isDown = true; startX = pt(e) - el.offsetLeft; scrollLeft = el.scrollLeft; };
    const move = (e) => { if (!isDown) return; e.preventDefault(); const x = pt(e) - el.offsetLeft; el.scrollLeft = scrollLeft - (x - startX); };
    const up = () => (isDown = false);

    el.addEventListener('mousedown', down);
    el.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
    el.addEventListener('touchstart', down, { passive: true });
    el.addEventListener('touchmove', move,  { passive: false });
    window.addEventListener('touchend', up);

    return () => {
      el.removeEventListener('mousedown', down);
      el.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
      el.removeEventListener('touchstart', down);
      el.removeEventListener('touchmove', move);
      window.removeEventListener('touchend', up);
    };
  }, []);

  // ancho de una “página”
  const pageDeltaPx = () => {
    const track = trackRef.current;
    if (!track) return 0;
    const card = track.querySelector('.ps-card');
    if (!card) return 0;
    const rect = card.getBoundingClientRect();
    const stylesTrack = getComputedStyle(track);
    const gap = parseFloat(stylesTrack.gap || stylesTrack.columnGap || 0);
    return rect.width + gap;
    // eslint-disable-next-line
  };

  const go = (dir) => {
    const delta = pageDeltaPx();
    if (!delta) return;
    trackRef.current?.scrollBy({ left: dir * delta, behavior: 'smooth' });
  };

  // Fallback a modo legacy
  const slides = groups && groups.length
    ? groups
    : images.map(img => ({ id: img.id, products: [img] }));

  return (
    <div className="ps-root" id={id} ref={rootRef}>
      <button className="ps-nav prev" onClick={() => go(-1)} aria-label="Anterior">‹</button>

      <div className="ps-track" ref={trackRef}>
        {slides.map((g, idx) => {
          const items = g.products || [];
          const clsVar = g.variant ? `pg-${g.variant}` : '';
          return (
            <div className={`ps-card ${clsVar}`} key={g.id ?? idx}>
              {/* grid interno del slide */}
              <div className="pg-grid">
                {items.map((p, i) => (
                  <a key={p.id ?? i} className="pg-item" href={`/producto/${p.id}`}>
                    <div className="pg-thumb">
                      <img src={p.imageUrl || p.image || '/placeholder.png'} alt={p.name || ''} loading="lazy" />
                    </div>
                    {/* meta sólo en variant 'cards' */}
                    {g.variant === 'cards' && (
                      <div className="pg-meta">
                        <div className="pg-name">{p.name || 'producto'}</div>
                        <div className="pg-price">{p.priceLabel || ''}</div>
                      </div>
                    )}
                  </a>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <button className="ps-nav next" onClick={() => go(1)} aria-label="Siguiente">›</button>

      <style>{`
        :root{
          --ps-gap:18px;
          --ps-card-bg:#fff;
          --ps-border:#e9e9e9;
          --ps-shadow:0 8px 24px rgba(0,0,0,.08);
          --ps-yellow:#F7D34A;
        }

        .ps-root{
          position:relative;
          width:100%;
        }

        .ps-track{
          display:grid;
          grid-auto-flow:column;
          gap:18px;
          overflow:auto hidden;
          scroll-behavior:smooth;
          scrollbar-width:none;
          -ms-overflow-style:none;
          padding:0 44px;   /* deja espacio para las flechas */
        }
        .ps-track::-webkit-scrollbar{ display:none; }

        .ps-card{
          background:transparent;
          min-width:100%;
        }

        /* GRID interno del slide */
        .pg-grid{
          display:grid;
          gap:18px;
          grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
        }

        /* Ítem “cards” (imagen + meta) */
        .pg-cards .pg-item{
          display:flex; flex-direction:column; text-decoration:none; color:#111;
          background:var(--ps-card-bg); border:1px solid var(--ps-border);
          border-radius:16px; box-shadow:var(--ps-shadow);
          transition:transform .12s ease, box-shadow .12s ease;
        }
        .pg-cards .pg-item:hover{ transform:translateY(-2px); box-shadow:0 12px 26px rgba(0,0,0,.12); }
        .pg-thumb{ aspect-ratio:1/1; width:100%; overflow:hidden; border-top-left-radius:16px; border-top-right-radius:16px; }
        .pg-thumb img{ width:100%; height:100%; object-fit:cover; display:block; }
        .pg-meta{ padding:10px 12px 12px; }
        .pg-name{ font-weight:800; font-size:18px; line-height:1.1; margin:0 0 6px 0; }
        .pg-price{ font-weight:900; font-size:20px; }

        /* Ítem genérico (modo legacy: solo imagen) */
        .pg-item:not(.pg-cards .pg-item){
          display:block;
        }

        /* Flechas */
        .ps-nav{
          position:absolute; top:50%; transform:translateY(-50%);
          width:38px; height:38px; border-radius:999px; border:0;
          display:grid; place-items:center; cursor:pointer;
          background:#000; color:#fff; opacity:.9;
          box-shadow:0 10px 24px rgba(0,0,0,.15);
        }
        .ps-nav:hover{ opacity:1; }
        .ps-nav.prev{ left:4px; }
        .ps-nav.next{ right:4px; }

        @media (min-width:900px){
          .pg-grid{ gap:22px; }
          .pg-name{ font-size:20px; }
          .pg-price{ font-size:22px; }
          .ps-nav{ width:42px; height:42px; }
        }
      `}</style>
    </div>
  );
}
